# -*- coding: utf-8 -*-
"""Generate CANopenNode V4-style OD.h / OD.c from an EdsDocument."""

from __future__ import annotations

from datetime import date
from typing import Dict, List, Tuple

from _shared.edsparse import EdsDocument, OdEntry

from .types import (
    access_oda_flags,
    byte_size,
    ctype_info,
    group_by_index,
    is_var_entry,
    parse_default,
    var_name,
)


def _banner(doc: EdsDocument, node_name: str) -> str:
    path = doc.path or "(unsaved)"
    vendor = doc.device_info.get("VendorName", "")
    product = doc.device_info.get("ProductName", "")
    return "\n".join([
        "/*",
        " * CANopen object dictionary — CANopenNode V4 style",
        " * Generated by openbus canopen_codegen on %s" % date.today().isoformat(),
        " * Node: %s" % node_name,
        " * Source: %s" % path,
        " * Device: %s / %s" % (vendor, product),
        " *",
        " * Place OD.h / OD.c next to your CANopenNode application and",
        " * #include \"OD.h\". See canopen_codegen/stacks/README.md.",
        " */",
        "",
    ])


def _storage_decls(entries: List[OdEntry]) -> Tuple[str, str, List[Tuple[OdEntry, str]]]:
    """Return (struct fields, initializers, [(entry, field_name), ...])."""
    fields = []
    inits = []
    mapping: List[Tuple[OdEntry, str]] = []
    for e in entries:
        if not is_var_entry(e):
            continue
        info = ctype_info(e.data_type)
        fname = var_name(e)
        size = byte_size(e.data_type)
        if info.is_string or info.is_domain:
            fields.append("    %s %s[%d];" % (info.c_type, fname, size))
            lit = parse_default(e.effective_value(), e.data_type)
            if lit.startswith('"'):
                inits.append("    .%s = %s," % (fname, lit))
            else:
                inits.append("    .%s = {0}," % fname)
        else:
            fields.append("    %s %s;" % (info.c_type, fname))
            inits.append("    .%s = %s," % (
                fname, parse_default(e.effective_value(), e.data_type)))
        mapping.append((e, fname))
    return "\n".join(fields), "\n".join(inits), mapping


def generate_od_h(doc: EdsDocument, node_name: str = "OD") -> str:
    entries = list(doc.entries)
    fields, _inits, mapping = _storage_decls(entries)
    lines = [_banner(doc, node_name)]
    lines.append("#ifndef OD_H")
    lines.append("#define OD_H")
    lines.append("")
    lines.append("#include <stdint.h>")
    lines.append("#include <stdbool.h>")
    lines.append("#include <stddef.h>")
    lines.append("")
    lines.append("/* Minimal ODA flags (compatible naming with CANopenNode V4). */")
    lines.append("#ifndef ODA_SDO_R")
    lines.append("#define ODA_SDO_R   0x01")
    lines.append("#define ODA_SDO_W   0x02")
    lines.append("#define ODA_TPDO    0x04")
    lines.append("#define ODA_RPDO    0x08")
    lines.append("#define ODA_MB      0x10")
    lines.append("#endif")
    lines.append("")
    lines.append("typedef struct {")
    lines.append("    uint16_t index;")
    lines.append("    uint8_t  subIndex;")
    lines.append("    uint8_t  attribute;  /* ODA_* */")
    lines.append("    uint16_t dataLength;")
    lines.append("    void    *dataOrig;")
    lines.append("} OD_Entry_t;")
    lines.append("")
    lines.append("typedef struct {")
    if fields:
        lines.append(fields)
    else:
        lines.append("    uint8_t _placeholder;")
    lines.append("} OD_RAM_t;")
    lines.append("")
    lines.append("extern OD_RAM_t OD_RAM;")
    lines.append("extern const OD_Entry_t OD_entryList[];")
    lines.append("extern const uint16_t OD_entryCount;")
    lines.append("")
    lines.append("/* Convenience pointers for application code */")
    for e, fname in mapping:
        info = ctype_info(e.data_type)
        comment = "/* 0x%04X:%02X %s */" % (e.index, e.subindex, e.name or "")
        if info.is_string or info.is_domain:
            lines.append("#define OD_%s  (OD_RAM.%s)  %s" % (fname, fname, comment))
        else:
            lines.append("#define OD_%s  (&OD_RAM.%s)  %s" % (fname, fname, comment))
    lines.append("")
    lines.append("#endif /* OD_H */")
    lines.append("")
    return "\n".join(lines)


def generate_od_c(doc: EdsDocument, node_name: str = "OD") -> str:
    entries = list(doc.entries)
    _fields, inits, mapping = _storage_decls(entries)
    lines = [_banner(doc, node_name)]
    lines.append('#include "OD.h"')
    lines.append("")
    lines.append("OD_RAM_t OD_RAM = {")
    if inits:
        lines.append(inits)
    lines.append("};")
    lines.append("")
    lines.append("const OD_Entry_t OD_entryList[] = {")
    for e, fname in mapping:
        info = ctype_info(e.data_type)
        length = byte_size(e.data_type)
        flags = access_oda_flags(e.access_type, e.pdo_mapping)
        ptr = "OD_RAM.%s" % fname
        lines.append(
            "    { 0x%04X, 0x%02X, %s, %d, (void*)%s }, /* %s */"
            % (e.index, e.subindex, flags, length, ptr, e.name or ""))
    if not mapping:
        lines.append("    { 0, 0, 0, 0, NULL },")
    lines.append("};")
    lines.append("")
    lines.append(
        "const uint16_t OD_entryCount = "
        "(uint16_t)(sizeof(OD_entryList) / sizeof(OD_entryList[0]));")
    lines.append("")
    return "\n".join(lines)


def generate(doc: EdsDocument, node_name: str = "OD") -> Dict[str, str]:
    return {
        "OD.h": generate_od_h(doc, node_name),
        "OD.c": generate_od_c(doc, node_name),
    }
